mapper.insert:
INSERT IGNORE INTO rag_projection_repair_audit (
    repair_id, index_generation_id, revision_id, batch_no, work_key,
    input_fingerprint, missing_ids_fingerprint, missing_count, state, requested_at
) SELECT
    #{repairId}, #{generationId}, #{revisionId}, #{batchNo}, #{workKey},
    #{inputFingerprint}, #{missingIdsFingerprint}, #{missingCount}, 'QUEUED', #{requestedAt}
FROM retrieval_vector_batch batch
JOIN rag_index_generation generation ON generation.id = batch.index_generation_id
WHERE batch.revision_id = #{revisionId} AND batch.index_generation_id = #{generationId}
  AND batch.batch_no = #{batchNo} AND batch.input_fingerprint = #{batchInputFingerprint}
  AND batch.state = 'INDEXED' AND generation.state = 'ACTIVE'

INSERT IGNORE INTO rag_projection_reconciliation_cursor (
    index_generation_id, pagination_token, updated_at
) VALUES (#{generationId}, NULL, #{updatedAt})

