SET pagination_token = #{nextCursor}, updated_at = #{updatedAt}
WHERE index_generation_id = #{generationId}
  AND ((pagination_token IS NULL AND #{expectedCursor} IS NULL)
       OR pagination_token = #{expectedCursor})

